#include <chrono>
#include <filesystem>
#include <iostream>

int main()
{
    using namespace std::chrono_literals;
    const auto elapsed = 1s + 1500ms;
    const auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(elapsed);
    const auto seconds = std::chrono::duration_cast<std::chrono::seconds>(elapsed);
    const auto path = (std::filesystem::path{"library"} / "notes/../atlas.txt")
                          .lexically_normal();
    std::cout << millis.count() << " ms\n";
    std::cout << seconds.count() << " seconds\n";
    std::cout << path.generic_string() << '\n';
}
